import{_ as i,C as r,o as a,c as n,a2 as t,b as d,w as s,a as h,E as c,a3 as p}from"./chunks/framework.DcUGGC0F.js";const C=JSON.parse('{"title":"Deploying the server","description":"","frontmatter":{},"headers":[],"relativePath":"docs/deploying-the-server.md","filePath":"docs/deploying-the-server.md"}'),l={name:"docs/deploying-the-server.md"};function u(k,e,g,y,m,f){const o=r("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="deploying-the-server" tabindex="-1">Deploying the server <a class="header-anchor" href="#deploying-the-server" aria-label="Permalink to &quot;Deploying the server&quot;">​</a></h1><p>The server runs on one Linux machine as Docker containers, behind a shared Caddy for HTTPS. Health data must stay in the EU or Switzerland under the GDPR, so pick a host there (<a href="./architecture#accounts-and-security">architecture</a>). The server currently answers <code>/health</code> with its version; Postgres stays empty until accounts arrive (<a href="https://github.com/tkint/coach-poulpy/issues/25" target="_blank" rel="noreferrer">#25</a>).</p><p>The setup follows <a href="./adr/0019-the-server-runs-with-docker-compose-on-one-server">ADR 0019</a>. Deployment files are in <a href="https://github.com/tkint/coach-poulpy/tree/main/deploy" target="_blank" rel="noreferrer"><code>deploy/</code></a>, and each <a href="./releasing#the-server">release</a> includes a deployment bundle.</p><h2 id="the-containers" tabindex="-1">The containers <a class="header-anchor" href="#the-containers" aria-label="Permalink to &quot;The containers&quot;">​</a></h2>',4)),(a(),d(p,null,{default:s(()=>[c(o,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20internet((%22Internet%22))%20--%20%2280%20and%20443%22%20--%3E%20caddy%0A%20%20%20%20subgraph%20edgeproj%5B%22edge%20project%22%5D%0A%20%20%20%20%20%20%20%20caddy%5B%22caddy%20%C2%B7%20shared%20HTTPS%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20appproj%5B%22coach-poulpy%20project%22%5D%0A%20%20%20%20%20%20%20%20server%5B%22server%20%C2%B7%20coach-poulpy-server%3A8080%22%5D%0A%20%20%20%20%20%20%20%20postgres%5B(%22postgres%20%C2%B7%20postgres-data%22)%5D%0A%20%20%20%20end%0A%20%20%20%20caddy%20--%20%22edge%20network%22%20--%3E%20server%0A%20%20%20%20server%20--%20%22internal%20network%22%20--%3E%20postgres%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p>Only Caddy publishes ports. The server joins the external <code>edge</code> network using a unique alias and the private <code>internal</code> network; Postgres joins only <code>internal</code>. The app and edge are separate Compose projects, so stopping the app leaves Caddy running. The shared network is for trusted applications: containers on it can reach each other&#39;s app ports.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>Linux with Python 3, Docker Engine and Docker Compose.</li><li>About 1 GB of free memory; the server is capped at 512 MB. Images are built in CI, not on the machine.</li><li>An API hostname (<code>api.coach-poulpy.com</code>) whose DNS A/AAAA records point to the machine. The landing site and the web app get their own hostnames and containers later (<a href="./adr/0021-the-landing-site-the-app-and-the-api-have-their-own-hostname">ADR 0021</a>).</li><li>SSH and ports 80/443 open (TCP, plus UDP 443 for HTTP/3).</li></ul><p>If <code>ghcr.io/tkint/coach-poulpy-server</code> is private, log the machine in once with a token that can read packages: <code>docker login ghcr.io</code>.</p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><p>Everything is deployed from GitHub; you don&#39;t log in to the machine for it. Set up the <strong>Deploy</strong> workflow once (<a href="./releasing#deploy-the-server">Releasing</a>), with <code>DOMAIN</code> and <code>POSTGRES_PASSWORD</code> in the <code>production</code> environment, then run <strong>Actions &gt; Deploy &gt; Run workflow</strong> with <code>latest</code> or a version. Check it with <code>curl https://api.coach-poulpy.com/health</code>.</p><p>The workflow writes <code>~/coach-poulpy/.env</code> from those settings (replaced on every run, so change settings in GitHub, not on the machine), uploads <code>compose.yaml</code> and the site file to <code>~/coach-poulpy</code>, and the shared Caddy to <code>~/caddy</code>. On the machine, <code>~/caddy/deploy.py</code> then:</p><ul><li>creates the external <code>edge</code> network and starts Caddy if needed,</li><li>pulls and starts the server and Postgres,</li><li>adds the site to Caddy through its admin API, or replaces it if already there.</li></ul><p>Caddy keeps the configuration it receives through the API in its <code>caddy-config</code> volume and resumes it after a restart; <code>bootstrap.json</code> is only used before the first site is added. Other sites on the same Caddy are left alone, and deployments wait for each other. To change the hostname, update <code>DOMAIN</code> in GitHub and deploy again. HTTPS errors are usually caused by DNS or blocked ports; inspect <code>cd ~/caddy &amp;&amp; docker compose logs caddy</code>.</p><p><code>POSTGRES_PASSWORD</code> only takes effect when the Postgres volume is first created; changing it later needs a password change inside Postgres too.</p><p>If another Caddy already holds ports 80/443, remove that container once before the first deploy (<code>docker rm -f &lt;container&gt;</code>); the shared Caddy requests the certificates again. Never use <code>docker compose down -v</code>: it deletes the volumes.</p><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>Postgres has nothing to back up until accounts arrive. After that, dump it nightly and store the dumps off-machine in the EU or Switzerland:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/coach-poulpy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Fc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> coachpoulpy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/coachpoulpy-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.dump</span></span></code></pre></div><p>Restore with <code>pg_restore -U coachpoulpy -d coachpoulpy --clean</code>, fed through <code>docker compose exec -T postgres</code>. Back up <code>.env</code> and the shared edge&#39;s configuration and migration state as well. Losing Caddy&#39;s certificate volume requires issuing new certificates.</p>`,15))])}const F=i(l,[["render",u]]);export{C as __pageData,F as default};
